Value.Calculation:
ExecuteSQL (
	"SELECT PrimaryKey, BrojNivelacije, DatumNivelacije, UkupnoRazlika
	 FROM Nivelacija
	 WHERE ForeignKeyCompanyID = ?
	   AND Status = 'Knjižena'
	   AND DatumNivelacije >= ?
	   AND DatumNivelacije <= ?
	 ORDER BY DatumNivelacije, BrojNivelacije" ;
	Char ( 9 ) ;
	Char ( 13 ) ;
	$companyID ;
	GetAsDate ( $datumOd ) ;
	GetAsDate ( $datumDo )
)

JSONSetElement ( "{}" ;
	[ "datum" ; $datum ; JSONString ] ;
	[ "opis" ; "Nivelacija cijena " & GetValue ( $cols ; 2 ) ; JSONString ] ;
	[ "brojDokumenta" ; GetValue ( $cols ; 2 ) ; JSONString ] ;
	[ "zaduzenje" ; If ( $razlika > 0 ; $razlika ; 0 ) ; JSONNumber ] ;
	[ "razduzenje" ; If ( $razlika < 0 ; Abs ( $razlika ) ; 0 ) ; JSONNumber ] ;
	[ "tip" ; "Nivelacija" ; JSONString ] ;
	[ "sortDatum" ; date.format ( $datum ; "yyyy-mm-dd" ) ; JSONString ] ;
	[ "sortOrder" ; 2 ; JSONNumber ] ;
	[ "documentID" ; GetValue ( $cols ; 1 ) ; JSONString ]
)
